#include "MainComponent.h"
#include "VocalTools.h"
#include <cmath>
namespace {
juce::String u(const char* s){return juce::String::fromUTF8(s);}
const juce::Colour background{0xff10151e},foreground{0xffe9eef6},muted{0xff8d9bb0},teal{0xff50d0bf},orange{0xffeaa76a};
class FxPanel final : public juce::Component,private juce::Timer {
    struct Control {juce::Label label;juce::Slider slider;std::atomic<float>* value;};
    StudioMain& owner;std::vector<std::unique_ptr<Control>> controls;juce::ComboBox preset;juce::ToggleButton bypass{u("Bypass FX")};juce::Label hint;
    void add(const juce::String& name,std::atomic<float>& value,double low,double high,double step,const juce::String& suffix){auto c=std::make_unique<Control>();c->value=&value;c->label.setText(name,juce::dontSendNotification);c->label.setJustificationType(juce::Justification::centred);c->slider.setRange(low,high,step);c->slider.setSliderStyle(juce::Slider::RotaryHorizontalVerticalDrag);c->slider.setTextBoxStyle(juce::Slider::TextBoxBelow,false,86,23);c->slider.setTextValueSuffix(suffix);auto* ptr=c.get();c->slider.onValueChange=[this,ptr]{if(!owner.isBusy())ptr->value->store(static_cast<float>(ptr->slider.getValue()));};addAndMakeVisible(c->label);addAndMakeVisible(c->slider);controls.push_back(std::move(c));}
    void timerCallback() override {const bool enabled=!owner.isBusy();for(auto& c:controls){c->slider.setEnabled(enabled);if(!c->slider.isMouseButtonDown())c->slider.setValue(c->value->load(),juce::dontSendNotification);}preset.setEnabled(enabled);bypass.setEnabled(enabled);bypass.setToggleState(owner.engine.fxBypass.load(),juce::dontSendNotification);}
public:
    explicit FxPanel(StudioMain& o):owner(o){auto& e=owner.engine;add("High-pass",e.highPass,40,180,1," Hz");add(u("Ấm / Warmth"),e.warmth,-8,6,.1," dB");add(u("Rõ / Presence"),e.presence,-6,8,.1," dB");add(u("Làm dịu gắt"),e.deharsh,0,1,.01,"");add("Threshold",e.threshold,-40,0,.5," dB");add("Ratio",e.ratio,1,8,.1,":1");add("Make-up",e.makeup,0,12,.1," dB");add(u("De-ess / Giảm xì"),e.deEss,0,1,.01,"");add(u("Vang / Reverb mix"),e.reverb,0,.4,.01,"");add("Decay / RT60",e.decaySeconds,.3,4,.05," s");add("Pre-delay",e.preDelayMs,0,100,1," ms");add(u("Damping / Độ tối"),e.damping,.05,.95,.01,"");add("Stereo width",e.width,0,1.5,.01,"");add("Echo / Delay mix",e.delay,0,.3,.01,"");add("Delay time",e.delayMs,40,800,1," ms");add(u("Delay lặp / Feedback"),e.delayFeedback,0,.65,.01,"");
        addAndMakeVisible(preset);preset.addItemList({"Clean Vocal","Warm Ballad","Pop Presence","Soft Room"},1);preset.setSelectedId(1,juce::dontSendNotification);preset.onChange=[this]{if(!owner.isBusy())owner.engine.selectPreset(preset.getSelectedItemIndex());};addAndMakeVisible(bypass);bypass.onClick=[this]{if(!owner.isBusy())owner.engine.fxBypass.store(bypass.getToggleState());};addAndMakeVisible(hint);hint.setText(u("FX dùng cho vocal bus và kiểm âm; WAV gốc được giữ riêng. Dùng tai nghe, tránh bật đồng thời Direct Monitor và kiểm âm FX. Giảm gain sound card nếu micro clip."),juce::dontSendNotification);hint.setColour(juce::Label::textColourId,muted);timerCallback();startTimerHz(15);
    }
    void resized() override {preset.setBounds(22,16,210,30);bypass.setBounds(252,16,180,30);const int top=64,bottom=getHeight()-70,w=(getWidth()-32)/4,h=(bottom-top)/4;for(std::size_t i=0;i<controls.size();++i){const int x=16+static_cast<int>(i%4)*w,y=top+static_cast<int>(i/4)*h;controls[i]->label.setBounds(x,y,w,23);controls[i]->slider.setBounds(x+12,y+24,w-24,h-29);}hint.setBounds(20,getHeight()-64,getWidth()-40,54);}
    void paint(juce::Graphics& g) override {g.fillAll(background);}
};
class PitchGraph final : public juce::Component {
public:std::shared_ptr<const vocal::PitchAnalysis> data;
    void paint(juce::Graphics& g) override {g.fillAll(juce::Colour(0xff19212d));const auto bounds=getLocalBounds().toFloat().reduced(12);g.setColour(muted);g.setFont(12);g.drawText(u(data&&!data->monophonic?"CHROMA / TONE · A4 = 440 Hz":"CAO ĐỘ VOCAL · A4 = 440 Hz"),14,6,getWidth()-28,22,juce::Justification::centredLeft);if(!data||data->frames.empty()){g.drawText(u("Dò một track để xem đường cao độ. Beat nhiều nhạc cụ dùng gợi ý tone, không dùng đường nốt đơn."),getLocalBounds().reduced(22),juce::Justification::centred);return;}
        if(!data->monophonic){const auto plot=bounds.withTrimmedTop(32);const double maximum=*std::max_element(data->chroma.begin(),data->chroma.end());for(int n=0;n<12;++n){const float w=plot.getWidth()/12,x=plot.getX()+n*w,h=maximum>0?static_cast<float>(data->chroma[n]/maximum)*(plot.getHeight()-24):0;g.setColour(teal);g.fillRoundedRectangle(x+5,plot.getBottom()-24-h,w-10,h,3);g.setColour(muted);g.drawText(vocal::noteName(60+n),static_cast<int>(x),static_cast<int>(plot.getBottom())-20,static_cast<int>(w),18,juce::Justification::centred);}return;}
        const auto plot=bounds.withTrimmedTop(26);double centre=data->medianHz>0?69+12*std::log2(data->medianHz/440):60;centre=std::round(centre);const double end=data->frames.back().seconds;for(int n=-12;n<=12;n+=3){const float y=plot.getCentreY()-n*plot.getHeight()/26;g.setColour(juce::Colour(0xff2a3545));g.drawHorizontalLine(static_cast<int>(y),plot.getX()+28,plot.getRight());g.setColour(muted);g.drawText(vocal::noteName(centre+n),static_cast<int>(plot.getX()),static_cast<int>(y)-8,28,16,juce::Justification::centredLeft);}
        juce::Path path;bool connected=false;for(const auto& frame:data->frames){if(frame.confidence<.8){connected=false;continue;}const float x=plot.getX()+30+static_cast<float>(frame.seconds/juce::jmax(.01,end))*(plot.getWidth()-32),y=plot.getCentreY()-static_cast<float>(frame.midi-centre)*plot.getHeight()/26;if(!connected){path.startNewSubPath(x,y);connected=true;}else path.lineTo(x,y);}g.setColour(orange);g.strokePath(path,juce::PathStrokeType(1.6f));}
};
class PitchPanel final : public juce::Component,private juce::Timer {
    StudioMain& owner;PitchGraph graph;juce::Label description,result,shiftLabel,centsLabel,amountLabel,speedLabel,toleranceLabel,keyLabel,progressLabel;juce::ComboBox key;juce::Slider shift,cents,amount,speed,tolerance;juce::ToggleButton automatic{u("Chỉnh phô giọng đơn")},formants{u("Giữ formant / màu giọng")},repair{u("Làm dịu clip nhẹ (không cứu vỡ nặng)")};juce::TextButton analyse{u("Dò tone / nốt")},apply{u("Áp dụng bản sao")},restore{u("Về bản gốc")},cancel{u("Hủy tác vụ")};
    void setup(juce::Slider& slider,juce::Label& label,const juce::String& title,double low,double high,double step,double value,const juce::String& suffix){addAndMakeVisible(slider);addAndMakeVisible(label);label.setText(title,juce::dontSendNotification);slider.setRange(low,high,step);slider.setValue(value);slider.setSliderStyle(juce::Slider::LinearHorizontal);slider.setTextBoxStyle(juce::Slider::TextBoxRight,false,90,25);slider.setTextValueSuffix(suffix);}
    void timerCallback() override {const bool enabled=owner.canEdit()&&owner.selected>=0;analyse.setEnabled(enabled);apply.setEnabled(enabled);restore.setEnabled(enabled);cancel.setEnabled(owner.isBusy());for(auto* c:std::initializer_list<juce::Component*>{&shift,&cents,&amount,&speed,&tolerance,&key,&automatic,&formants,&repair})c->setEnabled(!owner.isBusy());automatic.setEnabled(!owner.isBusy()&&!owner.engine.isAntaresActive());if(owner.engine.isAntaresActive())automatic.setToggleState(false,juce::dontSendNotification);result.setText(owner.toneStatus,juce::dontSendNotification);if(graph.data!=owner.pitchAnalysis){graph.data=owner.pitchAnalysis;graph.repaint();}progressLabel.setText(owner.isBusy()?u("Đang xử lý · ")+juce::String(static_cast<int>(owner.toolsProgress()*100))+"%":u("Xử lý vào file mới, giữ nguyên nhịp và thời lượng. Có thể quay lại WAV gốc."),juce::dontSendNotification);}
public:
    void refreshNow(){timerCallback();}
    explicit PitchPanel(StudioMain& o):owner(o){for(juce::Component* c:std::initializer_list<juce::Component*>{&graph,&description,&result,&keyLabel,&key,&automatic,&formants,&repair,&analyse,&apply,&restore,&cancel,&progressLabel})addAndMakeVisible(c);description.setText(u("Chọn track ở timeline, rồi dò tone. Vocal đơn: dò nốt và chỉnh phô. Beat: dò giọng trưởng/thứ và nâng/hạ tone giữ tempo. Kết quả dò là gợi ý, cần nghe và kiểm tra lại."),juce::dontSendNotification);description.setColour(juce::Label::textColourId,muted);result.setColour(juce::Label::textColourId,teal);keyLabel.setText(u("Tone / thang âm đầu ra"),juce::dontSendNotification);key.addItem(u("Tự dò (ưu tiên beat)"),1);key.addItem("Chromatic (12 notes)",2);for(int mode=0;mode<2;++mode)for(int root=0;root<12;++root)key.addItem(vocal::noteName(60+root)+(mode?" minor":" major"),3+mode*12+root);key.setSelectedId(1);formants.setToggleState(true,juce::dontSendNotification);
        setup(shift,shiftLabel,u("Nâng / hạ tone"),-12,12,1,0," st");setup(cents,centsLabel,u("Tinh chỉnh"),-50,50,.1,0," cent");setup(amount,amountLabel,u("Mức chỉnh phô"),0,100,1,75," %");setup(speed,speedLabel,u("Tốc độ chỉnh (cao = tự nhiên)"),10,250,1,80," ms");setup(tolerance,toleranceLabel,u("Giữ rung tự nhiên / vùng bỏ qua"),0,35,1,12," cent");
        analyse.onClick=[this]{owner.analyseSelected();};apply.onClick=[this]{vocal::PitchOptions options;options.semitones=static_cast<float>(shift.getValue());options.cents=static_cast<float>(cents.getValue());options.correction=automatic.getToggleState()?static_cast<float>(amount.getValue()/100):0;options.retuneMs=static_cast<float>(speed.getValue());options.toleranceCents=static_cast<float>(tolerance.getValue());options.preserveFormants=formants.getToggleState();options.repairLightClip=repair.getToggleState();const int id=key.getSelectedId();options.autoKey=id==1;options.tonic=id>=3?(id-3)%12:-1;options.minor=id>=15;owner.applyPitch(options);};restore.onClick=[this]{owner.restorePitch();};cancel.onClick=[this]{owner.cancelToolsWork();};timerCallback();startTimerHz(10);
    }
    void resized() override {const int w=getWidth(),half=w/2;description.setBounds(20,12,w-40,48);result.setBounds(20,64,w-40,72);graph.setBounds(20,142,w-40,150);keyLabel.setBounds(22,306,170,25);key.setBounds(198,306,half-220,28);automatic.setBounds(half+12,306,half-32,28);formants.setBounds(22,343,half-44,26);repair.setBounds(half+12,343,half-32,26);const int row=383;shiftLabel.setBounds(20,row,190,24);shift.setBounds(208,row,half-228,28);centsLabel.setBounds(half+12,row,130,24);cents.setBounds(half+145,row,half-165,28);amountLabel.setBounds(20,row+44,190,25);amount.setBounds(208,row+44,half-228,28);speedLabel.setBounds(half+12,row+44,half-24,22);speed.setBounds(half+12,row+67,half-32,27);toleranceLabel.setBounds(20,row+92,260,24);tolerance.setBounds(290,row+92,w-312,28);analyse.setBounds(22,getHeight()-96,155,32);apply.setBounds(190,getHeight()-96,175,32);restore.setBounds(378,getHeight()-96,145,32);cancel.setBounds(w-160,getHeight()-96,138,32);progressLabel.setBounds(20,getHeight()-52,w-40,35);}
    void paint(juce::Graphics& g) override {g.fillAll(background);}
};
class Tools final : public juce::TabbedComponent {
    StudioLook look;PitchPanel* pitch=nullptr;
public:
    void refresh(){if(pitch)pitch->refreshNow();}
    explicit Tools(StudioMain& owner):TabbedComponent(juce::TabbedButtonBar::TabsAtTop){setLookAndFeel(&look);addTab(u("Vang / Vocal FX"),background,new FxPanel(owner),true);addTab(u("Tone / Chỉnh phô"),background,pitch=new PitchPanel(owner),true);addTab(u("Theo giọng tôi"),background,createSingerPanel(owner),true);addTab(u("Antares Key/Scale"),background,createAntaresPanel(owner),true);setSize(1040,800);}~Tools() override {setLookAndFeel(nullptr);}
};
}
juce::Component* createVocalTools(StudioMain& owner){return new Tools(owner);}

void refreshVocalTools(juce::Component& component){if(auto* tools=dynamic_cast<Tools*>(&component))tools->refresh();}
